314	pub(crate) fn get_partition_by_sort_exprs(
315	    input: &Arc<dyn ExecutionPlan>,
316	    partition_by_exprs: &[Arc<dyn PhysicalExpr>],
317	    ordered_partition_by_indices: &[usize],
318	) -> Result<LexOrdering> {
319	    let ordered_partition_exprs = ordered_partition_by_indices
320	        .iter()
321	        .map(|idx| Arc::clone(&partition_by_exprs[*idx]))
322	        .collect::<Vec<_>>();
323	    // Make sure ordered section doesn't move over the partition by expression
324	    assert!(ordered_partition_by_indices.len() <= partition_by_exprs.len());
325	    let (ordering, _) = input
326	        .equivalence_properties()
327	        .find_longest_permutation(&ordered_partition_exprs);
328	    if ordering.len() == ordered_partition_exprs.len() {
329	        Ok(ordering)
330	    } else {
331	        exec_err!("Expects PARTITION BY expression to be ordered")
332	    }
333	}
