368	/// Constructs the best-fitting windowing operator (a `WindowAggExec` or a
369	/// `BoundedWindowExec`) for the given `input` according to the specifications
370	/// of `window_exprs` and `physical_partition_keys`. Here, best-fitting means
371	/// not requiring additional sorting and/or partitioning for the given input.
372	/// - A return value of `None` represents that there is no way to construct a
373	///   windowing operator that doesn't need additional sorting/partitioning for
374	///   the given input. Existing ordering should be changed to run the given
375	///   windowing operation.
376	/// - A `Some(window exec)` value contains the optimal windowing operator (a
377	///   `WindowAggExec` or a `BoundedWindowExec`) for the given input.
378	pub fn get_best_fitting_window(
379	    window_exprs: &[Arc<dyn WindowExpr>],
380	    input: &Arc<dyn ExecutionPlan>,
381	    // These are the partition keys used during repartitioning.
382	    // They are either the same with `window_expr`'s PARTITION BY columns,
383	    // or it is empty if partitioning is not desirable for this windowing operator.
384	    physical_partition_keys: &[Arc<dyn PhysicalExpr>],
385	) -> Result<Option<Arc<dyn ExecutionPlan>>> {
